import random


def strategy(history, rng):
    n = len(history)

    if n == 0:
        return 'C'

    me = [h[0] for h in history]
    op = [h[1] for h in history]

    # Count cooperation levels
    my_c = 0
    op_c = 0
    for a in me:
        if a == 'C':
            my_c += 1
    for a in op:
        if a == 'C':
            op_c += 1

    # If opponent has been mostly cooperative, be nice/sticky until provoked.
    if op_c >= n - max(1, n // 10):
        # retaliate only for recent defection
        if op[-1] == 'D':
            return 'D'
        return 'C'

    # If opponent mostly defects, exploit a bit but avoid getting stuck in DD.
    if op_c <= n // 3:
        # occasional cooperation to test/re-start
        if me[-1] == 'D' and op[-1] == 'D':
            return 'C'
        if op[-1] == 'D':
            return 'D'
        return 'C'

    # Mid game: tit-for-tat with mild forgiveness and late-game pressure.
    last_me = me[-1]
    last_op = op[-1]

    if last_op == 'D':
        # Forgive sometimes, especially if we defected last too
        if last_me == 'D':
            return 'C'
        if rng.random() < 0.15:
            return 'C'
        return 'D'

    # Opponent cooperated last
    if n > 85:
        # Near the end, defect more to grab payoff
        return 'D' if rng.random() < 0.35 else 'C'
    return 'C'
